import {
  Checkbox as AriaCheckbox,
  CheckboxGroup as AriaCheckboxGroup,
  FieldError as AriaFieldError,
  Label as AriaLabel,
  Text as AriaText,
} from 'react-aria-components'
import type {
  CheckboxGroupProps as AriaCheckboxGroupProps,
  CheckboxProps as AriaCheckboxProps,
  FieldErrorProps as AriaFieldErrorProps,
  LabelProps as AriaLabelProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { ERROR, HINT, LABEL } from '../field'

/**
 * The sheet's `.ds-check`. Note the radius: the sheet squares off its buttons and
 * inputs but gives the selection controls the 2px a checkbox is expected to have,
 * so `rounded-none` is deliberately not applied here.
 *
 * Every state is published as a custom property rather than applied to the
 * indicator directly. The indicator is a child, so a rule reaching it must go
 * through a group variant — and group variants sort at the *same* specificity as a
 * plain utility (Tailwind wraps them in `:where(...)`), leaving the outcome to
 * source order. A `group-data-[hovered]:border-foreground` therefore loses to the
 * indicator's own `border-input`, silently. Publishing a property here means
 * the ordinary cascade decides, because both rules land on this one element and
 * `[data-selected][data-hovered]` plainly outranks `[data-hovered]`.
 *
 * The names are `--selection-*` so that `Radio` can publish the same set and its
 * own indicator can read them without knowing which one it is inside.
 */
const CONTROL = [
  'group/selection inline-flex items-center gap-2.5',
  'cursor-pointer select-none',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
  // rest
  '[--selection-border:var(--color-input)]',
  '[--selection-bg:transparent]',
  '[--selection-mark:0]',
  '[--selection-mark-dash:0]',
  '[--selection-scale:0.4]',
  'motion-reduce:[--selection-scale:1]',
  '[--selection-ring:transparent]',
  // hover strengthens the border...
  'data-[hovered]:[--selection-border:var(--color-foreground)]',
  // ...selected fills it, shows the tick and scales the centre...
  'data-[selected]:[--selection-border:var(--color-primary)]',
  'data-[selected]:[--selection-bg:var(--color-primary)]',
  // Written as an exclusion rather than as a plain `data-[selected]`, because an indeterminate
  // checkbox is usually also a selected one and the two rules would tie on specificity: only one
  // of them may match.
  'data-[selected]:not-data-[indeterminate]:[--selection-mark:1]',
  'data-[selected]:[--selection-scale:1]',
  // ...and a checked control inverts on hover, the sheet's own `:hover` pair.
  'data-[selected]:data-[hovered]:[--selection-border:var(--color-foreground)]',
  'data-[selected]:data-[hovered]:[--selection-bg:var(--color-foreground)]',
  // ...and some-of-the-above fills the same way but shows a dash instead of a tick, which is the
  // whole difference between "all of it" and "some of it".
  'data-[indeterminate]:[--selection-border:var(--color-primary)]',
  'data-[indeterminate]:[--selection-bg:var(--color-primary)]',
  'data-[indeterminate]:[--selection-mark-dash:1]',
  'data-[indeterminate]:[--selection-scale:1]',
  // The ring is drawn on the indicator, because the control is a 1x1 invisible
  // input.
  'data-[focus-visible]:[--selection-ring:var(--color-primary)]',
].join(' ')

const BOX = [
  'grid size-[18px] flex-none place-items-center',
  'rounded-[2px] border border-(--selection-border) bg-(--selection-bg)',
  // A transparent outline rather than `outline-none`, so the ring fades in with
  // everything else instead of switching the outline on and off.
  'outline-1 outline-offset-[3px] outline-(--selection-ring)',
  'transition-[background-color,border-color,outline-color] duration-(--duration-fast) ease-pulse',
].join(' ')

/**
 * The tick is always in the DOM and fades in, as the sheet does — no layout shift
 * when it appears, and nothing to mount. It is sized in `rem` rather than `cap`,
 * because the box is a fixed 18px and does not scale with the type.
 */
const MARK = [
  // Both the tick and the dash sit in the box's single grid cell, so swapping one for the other
  // cannot change the box's size.
  'col-start-1 row-start-1',
  // The tick scales in as the box fills — the value the root publishes and that nothing read
  // until now, so the "scales the centre" the comment above describes never happened.
  'size-[11px] text-ink opacity-(--selection-mark) scale-(--selection-scale)',
  'transition-[opacity,scale] duration-(--duration-fast) ease-pulse',
].join(' ')

/** The dash an indeterminate checkbox shows instead of a tick. */
const DASH = [
  'col-start-1 row-start-1',
  'h-0.5 w-[9px] bg-ink opacity-(--selection-mark-dash)',
  'transition-opacity duration-(--duration-fast) ease-pulse',
].join(' ')

/** The sheet's `.ds-check-label`: 13px, foreground at 80%. */
const TEXT = 'text-[13px] text-foreground/80'

/**
 * The sheet's `<fieldset class="stack ds-field">`: legend, controls, then the
 * hint that explains them.
 *
 * `group` is here for `LABEL`'s required marker, which is drawn from the group's
 * own `data-required`. It is safe next to the controls' `group/selection`: that one
 * is named, so the two cannot be confused.
 */
const GROUP = 'group flex flex-col gap-2.5'

const Tick = (
  <svg
    viewBox="0 0 11 9"
    fill="none"
    aria-hidden="true"
    data-slot="mark"
    className={MARK}
  >
    <path
      d="M1.5 4.5L4.2 7.2L9.5 1.5"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
)

export interface CheckboxProps extends Omit<
  AriaCheckboxProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'isSelected'
  | 'defaultSelected'
  | 'onChange'
  | 'children'
  | 'className'
  | 'ref'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLLabelElement>
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaCheckboxProps['isDisabled']
  /** Makes the value visible but not changeable. */
  isReadOnly?: AriaCheckboxProps['isReadOnly']
  isRequired?: AriaCheckboxProps['isRequired']
  isInvalid?: AriaCheckboxProps['isInvalid']
  /**
   * The control owns its selection, so these live here rather than on a slot.
   * Outside a `Checkbox.Group` that means `defaultSelected` + `onChange(boolean)`;
   * inside one the group owns it and this is driven by the group's array.
   */
  /**
   * Shows a dash rather than a tick, for a checkbox standing in for a set of which only some are
   * chosen — a table's select-all, usually. It fills like a checked one either way; the mark is
   * what says "some" rather than "all". React Aria renders `data-indeterminate` for it.
   */
  isIndeterminate?: AriaCheckboxProps['isIndeterminate']
  isSelected?: AriaCheckboxProps['isSelected']
  defaultSelected?: AriaCheckboxProps['defaultSelected']
  onChange?: AriaCheckboxProps['onChange']
  /** Identifies this control to its `Checkbox.Group`. */
  value?: AriaCheckboxProps['value']
  className?: string
  /** `Checkbox.Indicator` and `Checkbox.Text`, in that order. */
  children?: React.ReactNode
}

export interface CheckboxGroupProps extends Omit<
  AriaCheckboxGroupProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'children'
  | 'className'
  | 'ref'
> {
  ref?: React.Ref<HTMLDivElement>
  isDisabled?: AriaCheckboxGroupProps['isDisabled']
  isReadOnly?: AriaCheckboxGroupProps['isReadOnly']
  isRequired?: AriaCheckboxGroupProps['isRequired']
  isInvalid?: AriaCheckboxGroupProps['isInvalid']
  /** The group owns the selection: an array of the selected `value`s. */
  value?: AriaCheckboxGroupProps['value']
  defaultValue?: AriaCheckboxGroupProps['defaultValue']
  onChange?: AriaCheckboxGroupProps['onChange']
  className?: string
  /** `Checkbox.Label`, the checkboxes, then `Checkbox.Hint` and `Checkbox.Error`. */
  children?: React.ReactNode
}

export interface CheckboxIndicatorProps extends React.HTMLAttributes<HTMLSpanElement> {
  className?: string
}

export interface CheckboxTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface CheckboxLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

export interface CheckboxHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface CheckboxFieldErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

/**
 * The box, with its tick — or its dash, when the checkbox is indeterminate. Use it as
 * `Checkbox.Indicator`, inside a `Checkbox`.
 *
 * Exported as `CheckboxIndicator` only so tooling can resolve it; consume the
 * compound form `Checkbox.Indicator`.
 */
export function CheckboxIndicator({
  className,
  ...props
}: CheckboxIndicatorProps) {
  return (
    <span
      data-slot="indicator"
      aria-hidden="true"
      className={[BOX, className].filter(Boolean).join(' ')}
      {...props}
    >
      {Tick}
      <span data-slot="dash" className={DASH} />
    </span>
  )
}

/**
 * The label of a single checkbox. Use it as `Checkbox.Text`, beside
 * `Checkbox.Indicator`. A bare text child renders too, just without the styling.
 *
 * Exported as `CheckboxText` only so tooling can resolve it; consume the compound
 * form `Checkbox.Text`.
 */
export function CheckboxText({
  className,
  children,
  ...props
}: CheckboxTextProps) {
  return (
    <span
      data-slot="text"
      className={[TEXT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * The legend for the group. Use it as `Checkbox.Label`, inside `Checkbox.Group`.
 *
 * Exported as `CheckboxLabel` only so tooling can resolve it; consume the compound
 * form `Checkbox.Label`.
 */
export function CheckboxLabel({
  className,
  children,
  ...props
}: CheckboxLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * The guidance under the group. Use it as `Checkbox.Hint`. React Aria wires it to
 * the group's `aria-describedby`.
 *
 * Exported as `CheckboxHint` only so tooling can resolve it; consume the compound
 * form `Checkbox.Hint`.
 */
export function CheckboxHint({
  className,
  children,
  ...props
}: CheckboxHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the group is `isInvalid`. Use it as
 * `Checkbox.Error`; React Aria renders nothing while the group is valid.
 *
 * Exported as `CheckboxFieldError` only so tooling can resolve it; consume the
 * compound form `Checkbox.Error`.
 */
export function CheckboxFieldError({
  className,
  ...props
}: CheckboxFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The group. Use it as `Checkbox.Group`. It owns the value, as an array of the
 * selected `value`s.
 *
 * Exported as `CheckboxGroup` only so tooling can resolve it; consume the compound
 * form `Checkbox.Group`.
 */
export function CheckboxGroup({
  ref,
  className,
  children,
  ...props
}: CheckboxGroupProps) {
  return (
    <AriaCheckboxGroup
      ref={ref}
      className={[GROUP, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCheckboxGroup>
  )
}

/**
 * Styled element. Not exported — `Checkbox` below is the public symbol, and docgen
 * reads the JSDoc from the *exported* declaration, not this one.
 */
function CheckboxControl({
  ref,
  className,
  children,
  ...props
}: CheckboxProps) {
  return (
    <AriaCheckbox
      ref={ref}
      className={[CONTROL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCheckbox>
  )
}

/**
 * A checkbox, and the group it can belong to — the sheet's `.ds-check`.
 *
 * ```tsx
 * <Checkbox.Group defaultValue={['slow']}>
 *   <Checkbox.Label>Alert me when</Checkbox.Label>
 *   <Checkbox value="down">
 *     <Checkbox.Indicator />
 *     <Checkbox.Text>Down</Checkbox.Text>
 *   </Checkbox>
 *   <Checkbox.Hint>Applies to every monitor.</Checkbox.Hint>
 *   <Checkbox.Error>Pick at least one.</Checkbox.Error>
 * </Checkbox.Group>
 * ```
 *
 * The slots are explicit, like `Button.Icon` and `Button.Text`:
 * `Checkbox.Indicator` draws the box and its tick, and `Checkbox.Text` the label. A
 * bare text child still renders, it just misses the label styling, so a missing
 * slot degrades rather than disappears.
 *
 * Alone, a `Checkbox` owns its selection: `defaultSelected` with
 * `onChange(boolean)`. Inside a `Checkbox.Group` the group owns it, as an array,
 * and `value` identifies the control to it.
 */
export const Checkbox = Object.assign(CheckboxControl, {
  Group: CheckboxGroup,
  Indicator: CheckboxIndicator,
  Text: CheckboxText,
  Label: CheckboxLabel,
  Hint: CheckboxHint,
  Error: CheckboxFieldError,
})

import {
  ColorField as AriaColorField,
  ColorFieldStateContext,
  FieldError as AriaFieldError,
  Input as AriaInput,
  Label as AriaLabel,
  Text as AriaText,
} from 'react-aria-components'
import type {
  ColorFieldProps as AriaColorFieldProps,
  FieldErrorProps as AriaFieldErrorProps,
  InputProps as AriaInputProps,
  LabelProps as AriaLabelProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { useContext } from 'react'
import type { ReactNode } from 'react'

import { ERROR, FIELD, GROUP, HINT, INPUT, LABEL } from '../field'

export interface ColorFieldProps extends Omit<
  AriaColorFieldProps,
  | 'children'
  | 'className'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'isDisabled'
  | 'isInvalid'
  | 'isRequired'
  | 'isReadOnly'
  | 'channel'
> {
  /** The colour as a `Color` — or a string it can parse. Controlled. */
  value?: AriaColorFieldProps['value']
  /** The colour it starts at, for uncontrolled use. */
  defaultValue?: AriaColorFieldProps['defaultValue']
  /** Called with the parsed colour, or `null` when the text is not one. */
  onChange?: AriaColorFieldProps['onChange']
  /** Disables the field. */
  isDisabled?: AriaColorFieldProps['isDisabled']
  /** Marks the field invalid from the outside, for a server's answer. */
  isInvalid?: AriaColorFieldProps['isInvalid']
  /** Marks it required and draws the label's marker. */
  isRequired?: AriaColorFieldProps['isRequired']
  /** Keeps the value readable and selectable but uneditable — and does not dim it. */
  isReadOnly?: AriaColorFieldProps['isReadOnly']
  /** Edits one channel rather than the whole hex value. */
  channel?: AriaColorFieldProps['channel']

  className?: string
  children?: ReactNode
}

export interface ColorFieldLabelProps extends Omit<
  AriaLabelProps,
  'className'
> {
  className?: string
}

export interface ColorFieldControlProps {
  className?: string
  children?: ReactNode
}

export interface ColorFieldSwatchProps {
  className?: string
}

export interface ColorFieldInputProps extends Omit<
  AriaInputProps,
  'className'
> {
  className?: string
}

export interface ColorFieldHintProps extends Omit<AriaTextProps, 'className'> {
  className?: string
}

export interface ColorFieldErrorProps extends Omit<
  AriaFieldErrorProps,
  'className'
> {
  className?: string
}

/**
 * The legend. Use it as `ColorField.Label`.
 *
 * Exported as `ColorFieldLabel` only so tooling can resolve it; consume the compound form
 * `ColorField.Label`.
 */
export function ColorFieldLabel({ className, ...props }: ColorFieldLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The row the swatch and the input share. Use it as `ColorField.Control`.
 *
 * **`ColorField`'s children are the whole column**, not a row — its own element is the field, exactly as
 * `TextField`'s is, and the legend, the control and the hint are its direct children. The swatch and the
 * input *are* a row, so they need one element between them and the column. Without it the hint renders
 * beside the input.
 *
 * Exported as `ColorFieldControl` only so tooling can resolve it; consume the compound form
 * `ColorField.Control`.
 */
export function ColorFieldControl({
  className,
  children,
}: ColorFieldControlProps) {
  return (
    <div
      data-slot="color-control"
      className={[GROUP, 'items-center gap-2', className]
        .filter(Boolean)
        .join(' ')}
    >
      {children}
    </div>
  )
}

/**
 * The colour the field currently holds, as a square. Use it as `ColorField.Swatch`.
 *
 * **It reads the field's own state** rather than being handed a colour, so it cannot drift from the
 * value in the input — the arrangement `Meter.Fill` and `Nav.Label` use. The state property is
 * **`colorValue`**, not `value`; there is no `value` on a `ColorFieldState`.
 *
 * An empty field paints **nothing**: a black square would claim there was a value, and there is not —
 * the same distinction a progress bar draws between "unknown" and "zero".
 *
 * Exported as `ColorFieldSwatch` only so tooling can resolve it; consume the compound form
 * `ColorField.Swatch`.
 */
export function ColorFieldSwatch({ className }: ColorFieldSwatchProps) {
  const state = useContext(ColorFieldStateContext)
  const color = state?.colorValue?.toString('hex')

  return (
    <span
      data-slot="swatch"
      aria-hidden="true"
      className={['size-6 shrink-0 border border-input', className]
        .filter(Boolean)
        .join(' ')}
      style={color ? { background: color } : undefined}
    />
  )
}

/**
 * The control. Use it as `ColorField.Input`.
 *
 * It keeps the shared `INPUT` — the same height, type and hairline — because a colour field is a text
 * field that happens to parse what you type as a colour: the hex digits are real segments you can step
 * and select, exactly as a date field's are.
 *
 * Exported as `ColorFieldInput` only so tooling can resolve it; consume the compound form
 * `ColorField.Input`.
 */
export function ColorFieldInput({ className, ...props }: ColorFieldInputProps) {
  return (
    <AriaInput
      data-slot="input"
      className={[INPUT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The guidance under the control. Use it as `ColorField.Hint`.
 *
 * Exported as `ColorFieldHint` only so tooling can resolve it; consume the compound form
 * `ColorField.Hint`.
 */
export function ColorFieldHint({ className, ...props }: ColorFieldHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The error, which renders nothing while the field is valid. Use it as `ColorField.Error`.
 *
 * Exported as `ColorFieldError` only so tooling can resolve it; consume the compound form
 * `ColorField.Error`.
 */
export function ColorFieldError({ className, ...props }: ColorFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A colour typed into a field, with a square showing what it is.
 *
 * ```tsx
 * <ColorField defaultValue={parseColor('#71FFF6')}>
 *   <ColorField.Label>Label colour</ColorField.Label>
 *   <ColorField.Control>
 *     <ColorField.Swatch />
 *     <ColorField.Input />
 *   </ColorField.Control>
 *   <ColorField.Hint>Hex, rgb() or oklch().</ColorField.Hint>
 *   <ColorField.Error>That is not a colour.</ColorField.Error>
 * </ColorField>
 * ```
 *
 * **It is a text field whose value happens to be a colour**, which is why it wears `field.ts`'s whole
 * anatomy — the legend, the hairline, the hint column, the error — and inherits every rule that file
 * already establishes, including the read-only behaviour and the resting boundary. A field that looked
 * like a native `<input type="color">` swatch would be the one control here with a different shape.
 *
 * **The square is a swatch, not the control.** The control is the text: a colour is something people
 * paste, and typing one is faster than dragging a picker to the value already in hand.
 *
 * **This is not a colour picker.** `ColorArea`, `ColorWheel` and `ColorSlider` exist for that and would
 * need a spectrum this design language does not have — Pulse's palette is four semantic accents, not a
 * gradient. A field is the honest half of the colour set to build here.
 */
function ColorFieldRoot({ className, children, ...props }: ColorFieldProps) {
  return (
    <AriaColorField
      data-slot="color-field"
      className={[FIELD, 'w-fit', className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaColorField>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const ColorField = Object.assign(ColorFieldRoot, {
  Label: ColorFieldLabel,
  Control: ColorFieldControl,
  Swatch: ColorFieldSwatch,
  Input: ColorFieldInput,
  Hint: ColorFieldHint,
  Error: ColorFieldError,
})

import {
  DateField as AriaDateField,
  DateInput as AriaDateInput,
  DateSegment as AriaDateSegment,
  FieldError as AriaFieldError,
  Group as AriaGroup,
  Label as AriaLabel,
  Text as AriaText,
} from 'react-aria-components'
import type {
  DateFieldProps as AriaDateFieldProps,
  DateInputProps as AriaDateInputProps,
  DateValue,
  FieldErrorProps as AriaFieldErrorProps,
  GroupProps as AriaGroupProps,
  LabelProps as AriaLabelProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { DATE_SEGMENT } from '../date'
import { FIELD_SIZES, INPUT, LABEL, HINT, ERROR } from '../field'
import type { FieldSize } from '../field'

/**
 * A segment, derived from what React Aria's `DateInput` hands its render function rather than
 * re-declared, so it cannot drift from the signature it has to match.
 */
type Segment = Parameters<NonNullable<AriaDateInputProps['children']>>[0]

export interface DateFieldProps<T extends DateValue> extends Omit<
  AriaDateFieldProps<T>,
  | 'children'
  | 'className'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'minValue'
  | 'maxValue'
> {
  /** The date. Controlled. */
  value?: AriaDateFieldProps<T>['value']
  /** The date it starts at, for uncontrolled use. */
  defaultValue?: AriaDateFieldProps<T>['defaultValue']
  /** Called with the date, or `null` when the field is cleared. */
  onChange?: AriaDateFieldProps<T>['onChange']
  /** Disables the field. */
  isDisabled?: AriaDateFieldProps<T>['isDisabled']
  /** Keeps the value readable but uneditable. */
  isReadOnly?: AriaDateFieldProps<T>['isReadOnly']
  /** Marks it required. */
  isRequired?: AriaDateFieldProps<T>['isRequired']
  /** Marks it invalid from the outside. */
  isInvalid?: AriaDateFieldProps<T>['isInvalid']
  /** The earliest selectable date. */
  minValue?: AriaDateFieldProps<T>['minValue']
  /** The latest selectable date. */
  maxValue?: AriaDateFieldProps<T>['maxValue']

  /** `sm | md | lg`, from the shared field table. */
  size?: FieldSize
  className?: string
  children?: React.ReactNode
}

export interface DateFieldLabelProps extends Omit<AriaLabelProps, 'className'> {
  className?: string
}

export interface DateFieldGroupProps extends Omit<AriaGroupProps, 'className'> {
  className?: string
}

export interface DateFieldInputProps extends Omit<
  AriaDateInputProps,
  'children' | 'className'
> {
  className?: string
}

export interface DateFieldHintProps extends Omit<AriaTextProps, 'className'> {
  className?: string
}

export interface DateFieldErrorProps extends Omit<
  AriaFieldErrorProps,
  'className'
> {
  className?: string
}

/** The bordered box the segments sit in. */
const GROUP = [
  'flex w-fit items-center',
  'border border-(--field-border) bg-card',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[focus-within]:border-primary',
  'data-[invalid]:border-destructive',
  'data-[disabled]:opacity-40',
].join(' ')

/**
 * A date typed into a field, with no calendar behind it.
 *
 * ```tsx
 * <DateField defaultValue={parseDate('2024-03-18')}>
 *   <DateField.Label>Starts on</DateField.Label>
 *   <DateField.Group>
 *     <DateField.Input />
 *   </DateField.Group>
 *   <DateField.Error>Choose a date.</DateField.Error>
 * </DateField>
 * ```
 *
 * **The segments are real, individually editable fields, and that is the whole point.** Each one
 * takes focus, the up and down arrows step it, and typing a digit advances to the next — so a date is
 * a date to a keyboard user rather than a string they have to guess the format of. A plain
 * `<input type="date">` gives the browser's own picker and no styling at all; a text input gives
 * nothing. This is the only one of the three where the parts are addressable.
 *
 * It shares `date.tsx` with `DatePicker` and `DateRangePicker`, so a segment looks the same whether
 * it arrived from typing or from a calendar — the same call `field.ts` makes for the text controls.
 *
 * **No picker, by design.** Use this when the date is known and typing it is faster; reach for
 * `DatePicker` when it has to be looked up. Putting a calendar here would make every date field a
 * two-step control for the sake of the occasional date nobody remembers.
 */
function DateFieldRoot<T extends DateValue>({
  size = 'md',
  className,
  children,
  ...props
}: DateFieldProps<T>) {
  return (
    <AriaDateField
      className={[
        FIELD_SIZES[size],
        '[--field-border:var(--color-input)]',
        '[--field-hover:var(--color-foreground)]',
        'flex flex-col gap-2',
        'data-[disabled]:cursor-not-allowed',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaDateField>
  )
}

/**
 * What the date is. Use it as `DateField.Label`.
 *
 * Exported as `DateFieldLabel` only so tooling can resolve it; consume the compound form
 * `DateField.Label`.
 */
export function DateFieldLabel({ className, ...props }: DateFieldLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The bordered box the segments sit in. Use it as `DateField.Group`.
 *
 * Exported as `DateFieldGroup` only so tooling can resolve it; consume the compound form
 * `DateField.Group`.
 */
export function DateFieldGroup({
  className,
  children,
  ...props
}: DateFieldGroupProps) {
  return (
    <AriaGroup
      // **`role="group"` is on the field root too**, so a story querying the role matches two elements
      // per field and a "three sizes" assertion counts six. `data-slot` names the bordered box, as it
      // does for the drop zone and the slider's grip.
      data-slot="date-group"
      className={[GROUP, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGroup>
  )
}

/**
 * The segments. Use it as `DateField.Input` — with no children it draws every segment of the date
 * from the render props, in the order the locale puts them.
 *
 * Exported as `DateFieldInput` only so tooling can resolve it; consume the compound form
 * `DateField.Input`.
 */
export function DateFieldInput({ className, ...props }: DateFieldInputProps) {
  return (
    <AriaDateInput
      className={[INPUT, 'flex w-auto items-center gap-0', className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {(segment: Segment) => (
        <AriaDateSegment segment={segment} className={DATE_SEGMENT} />
      )}
    </AriaDateInput>
  )
}

/**
 * A line of help under the field. Use it as `DateField.Hint`.
 *
 * Exported as `DateFieldHint` only so tooling can resolve it; consume the compound form
 * `DateField.Hint`.
 */
export function DateFieldHint({ className, ...props }: DateFieldHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The message shown while the field is invalid — including "incomplete", which for a date is the
 * common case. Use it as `DateField.Error`.
 *
 * Exported as `DateFieldError` only so tooling can resolve it; consume the compound form
 * `DateField.Error`.
 */
export function DateFieldError({ className, ...props }: DateFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A date typed into a field, with no calendar behind it. The compound form is the public symbol; the
 * root is named apart because a plain `function` decorated with `Object.assign` leaves TypeScript
 * unaware of the slots.
 */
export const DateField = Object.assign(DateFieldRoot, {
  Label: DateFieldLabel,
  Group: DateFieldGroup,
  Input: DateFieldInput,
  Hint: DateFieldHint,
  Error: DateFieldError,
})

import {
  Button as AriaButton,
  FieldError as AriaFieldError,
  Group as AriaGroup,
  Input as AriaInput,
  Label as AriaLabel,
  NumberField as AriaNumberField,
  Text as AriaText,
} from 'react-aria-components'
import type {
  FieldErrorProps as AriaFieldErrorProps,
  GroupProps as AriaGroupProps,
  InputProps as AriaInputProps,
  LabelProps as AriaLabelProps,
  NumberFieldProps as AriaNumberFieldProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { ERROR, FIELD, FIELD_SIZES, GROUP, HINT, INPUT, LABEL } from '../field'
import type { FieldSize } from '../field'

/**
 * The sheet has no number field — only a number's *typography*, in `.ds-num`, `.ds-num-sm` and
 * `.ds-num-alt`. So the field is the shared anatomy every control here uses, and the sheet's
 * contribution is the type: its numbers are letterspaced and, being mono, already tabular, which is
 * what makes a column of figures line up.
 *
 * The yellow stays with the readouts. `.ds-num` is an accent because a number in the sheet's
 * dashboard *is* the point of the row; a number being typed is one value among the others on the
 * form, and a field that shouts is a field nobody can read alongside its neighbours.
 */
const NUMBER_INPUT = [
  INPUT,
  // Tabular and letterspaced, the sheet's numeric signature — so the digits do not shuffle sideways
  // as they are typed, and a column of them lines up.
  'tabular-nums tracking-[0.35px]',
].join(' ')

/**
 * The trailing unit, the way the sheet builds one.
 *
 * It is **inside** the field, not beside it: the sheet's `.ds-input--unit` pads the input on that
 * side and its `.ds-unit` sits over the padding. Putting the buttons *after* the input instead
 * pushes them outside the border, because the shared `INPUT` is `w-full` — the one class a control
 * cannot argue with in a flex row, since both are `width` utilities and Tailwind's order, not the
 * author's, decides between them.
 *
 * `data-slot="counter"` is what asks the Group for the padding, through a rule `NumberField` adds
 * for itself rather than one `field.ts` has to know about. The two halves **stack**, so the unit is
 * a column the height of the field: that is the shape a spinner is read in, and `+` is on top for
 * the same reason it is on every other one.
 */
const COUNTER = [
  'absolute inset-y-0 end-0 z-10 flex w-8 flex-col',
  'border-s border-(--field-border)',
].join(' ')

const STEPPER = [
  'flex flex-1 items-center justify-center',
  'cursor-pointer text-foreground/70',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[hovered]:bg-foreground/5 data-[hovered]:text-foreground',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-[-3px]',
  'data-[focus-visible]:outline-ring',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
].join(' ')

/** The hairline between the two halves — the same divider the sheet draws between an input and its affix. */
const STEPPER_DIVIDE = 'border-b border-(--field-border)'

/** The sheet's caret, at 1.5 stroke, turned to point up and down. */
const ARROW = 'h-1 w-1.5'

function Stepper({ points }: { points: 'up' | 'down' }) {
  return (
    <svg viewBox="0 0 10 6" fill="none" aria-hidden="true" className={ARROW}>
      <path
        d="M1 1L5 5L9 1"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        transform={points === 'up' ? 'rotate(180 5 3)' : undefined}
      />
    </svg>
  )
}

export interface NumberFieldProps extends Omit<
  AriaNumberFieldProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'children'
  | 'className'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLDivElement>
  /** Sizes the control the same way a field is sized, through the shared tokens. */
  size?: FieldSize
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaNumberFieldProps['isDisabled']
  isReadOnly?: AriaNumberFieldProps['isReadOnly']
  isRequired?: AriaNumberFieldProps['isRequired']
  isInvalid?: AriaNumberFieldProps['isInvalid']
  /** The value is a number, or `null` for empty. Not a string. */
  value?: AriaNumberFieldProps['value']
  defaultValue?: AriaNumberFieldProps['defaultValue']
  onChange?: AriaNumberFieldProps['onChange']
  /** What one press of a stepper, or one press of an arrow key, is worth. */
  step?: AriaNumberFieldProps['step']
  minValue?: AriaNumberFieldProps['minValue']
  maxValue?: AriaNumberFieldProps['maxValue']
  /** How the value is formatted when the field is not being edited — a currency, a percentage. */
  formatOptions?: AriaNumberFieldProps['formatOptions']
  /**
   * Stops a scroll over the field from changing it. Worth turning on inside anything scrollable,
   * where a wheel meant for the page silently edits a number on the way past.
   */
  isWheelDisabled?: AriaNumberFieldProps['isWheelDisabled']
  className?: string
  /** `NumberField.Label`, `NumberField.Group`, then the hint and error. */
  children?: React.ReactNode
}

export interface NumberFieldLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

/**
 * The room the counter takes. A rule `NumberField` owns rather than one in `field.ts`, because a
 * counter is this component's affix and a text field has no use for it. 36px against the counter's
 * 32, so the value never touches the divider.
 */
const COUNTER_GUTTER = 'has-[[data-slot=counter]]:[&>[data-slot=input]]:pe-9'

export interface NumberFieldGroupProps extends Omit<
  AriaGroupProps,
  'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface NumberFieldInputProps extends Omit<
  AriaInputProps,
  'children' | 'className' | 'value' | 'defaultValue' | 'onChange'
> {
  className?: string
}

export interface NumberFieldCounterProps {
  className?: string
  /** Replaces the pair of arrows. Rarely wanted, and it is two children, not one. */
  children?: React.ReactNode
}

export interface NumberFieldHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface NumberFieldFieldErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

/**
 * The legend. Use it as `NumberField.Label`. The required marker comes from the field's own
 * `data-required`, so it cannot drift out of sync with `isRequired`.
 *
 * Exported as `NumberFieldLabel` only so tooling can resolve it; consume the compound form
 * `NumberField.Label`.
 */
export function NumberFieldLabel({
  className,
  children,
  ...props
}: NumberFieldLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * Wraps the input and its steppers. Use it as `NumberField.Group`.
 *
 * Exported as `NumberFieldGroup` only so tooling can resolve it; consume the compound form
 * `NumberField.Group`.
 */
export function NumberFieldGroup({
  className,
  children,
  ...props
}: NumberFieldGroupProps) {
  return (
    <AriaGroup
      className={[GROUP, COUNTER_GUTTER, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGroup>
  )
}

/**
 * The number. Use it as `NumberField.Input`. It is a text input underneath, so it can be typed
 * into, selected and undone like one — React Aria does the parsing and the formatting around it.
 *
 * Exported as `NumberFieldInput` only so tooling can resolve it; consume the compound form
 * `NumberField.Input`.
 */
export function NumberFieldInput({
  className,
  ...props
}: NumberFieldInputProps) {
  return (
    <AriaInput
      data-slot="input"
      className={[NUMBER_INPUT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The steppers. Use it as `NumberField.Counter`: one slot rather than two, because they are one
 * control — two halves of a single column, which is how a spinner is read. Splitting them into
 * `.Increment` and `.Decrement` invited a consumer to lay them out side by side, which is a
 * different and worse thing.
 *
 * `slot="increment"` and `slot="decrement"` are written here rather than left to the consumer, for
 * the same reason `Table.Selection` writes `slot="selection"`: the one attribute that makes it work
 * is the one nobody remembers, and getting it wrong still renders.
 *
 * Exported as `NumberFieldCounter` only so tooling can resolve it; consume the compound form
 * `NumberField.Counter`.
 */
export function NumberFieldCounter({
  className,
  children,
}: NumberFieldCounterProps) {
  return (
    <div
      data-slot="counter"
      className={[COUNTER, className].filter(Boolean).join(' ')}
    >
      {children ?? (
        <>
          {/* Up on top, the way every other spinner on the platform does it. */}
          <AriaButton
            slot="increment"
            className={`${STEPPER} ${STEPPER_DIVIDE}`}
          >
            <Stepper points="up" />
          </AriaButton>
          <AriaButton slot="decrement" className={STEPPER}>
            <Stepper points="down" />
          </AriaButton>
        </>
      )}
    </div>
  )
}

/**
 * The guidance under the control. Use it as `NumberField.Hint`.
 *
 * Exported as `NumberFieldHint` only so tooling can resolve it; consume the compound form
 * `NumberField.Hint`.
 */
export function NumberFieldHint({
  className,
  children,
  ...props
}: NumberFieldHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the field is `isInvalid`. Use it as `NumberField.Error`.
 *
 * Exported as `NumberFieldFieldError` only so tooling can resolve it; consume the compound form
 * `NumberField.Error`.
 */
export function NumberFieldFieldError({
  className,
  ...props
}: NumberFieldFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * Styled element. Not exported — `NumberField` below is the public symbol, and docgen reads the
 * JSDoc from the *exported* declaration, not this one.
 */
function NumberFieldRoot({
  ref,
  size = 'md',
  className,
  children,
  ...props
}: NumberFieldProps) {
  return (
    <AriaNumberField
      ref={ref}
      className={[FIELD, FIELD_SIZES[size], className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaNumberField>
  )
}

/**
 * A number — typed, stepped, or scrolled. The sheet has no number field in it, only a number's
 * *typography*, so the field is the shared anatomy and the sheet supplies the type: its numbers are
 * letterspaced and tabular, which is what makes a column of figures line up.
 *
 * ```tsx
 * <NumberField defaultValue={60} minValue={5} maxValue={600}>
 *   <NumberField.Label>Interval</NumberField.Label>
 *   <NumberField.Group>
 *     <NumberField.Input />
 *     <NumberField.Counter />
 *   </NumberField.Group>
 *   <NumberField.Hint>Seconds between checks.</NumberField.Hint>
 * </NumberField>
 * ```
 *
 * **The value is a number, not a string.** `onChange` gives a number or `null` — `null` for empty,
 * which is a real state a field has to be able to hold rather than a zero it did not mean.
 *
 * Two things React Aria does that make this worth not hand-rolling: the field stays a **text input**
 * underneath, so it can be typed, selected and undone like one while the parsing and formatting
 * happen around it; and `formatOptions` is what turns that into a currency or a percentage, so the
 * same field is a money field when it needs to be.
 *
 * `isWheelDisabled` is worth turning on inside anything scrollable — a wheel meant for the page
 * silently editing a number as it goes past is a small trap with no undo.
 */
export const NumberField = Object.assign(NumberFieldRoot, {
  Label: NumberFieldLabel,
  Group: NumberFieldGroup,
  Input: NumberFieldInput,
  Counter: NumberFieldCounter,
  Hint: NumberFieldHint,
  Error: NumberFieldFieldError,
})

import {
  FieldError as AriaFieldError,
  Label as AriaLabel,
  Radio as AriaRadio,
  RadioGroup as AriaRadioGroup,
  Text as AriaText,
} from 'react-aria-components'
import type {
  FieldErrorProps as AriaFieldErrorProps,
  LabelProps as AriaLabelProps,
  RadioGroupProps as AriaRadioGroupProps,
  RadioProps as AriaRadioProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { ERROR, HINT, LABEL } from '../field'

/**
 * The sheet's `.ds-radio`. The dot is a circle where the checkbox is a 2px-radius
 * square — the two exceptions to this system's `rounded-none`.
 *
 * States are published as custom properties here and read by the indicator, rather
 * than applied to it through a group variant. A group variant sorts at the same
 * specificity as a plain utility, so it silently loses to the indicator's own
 * `border-input`; a property set on this element wins the ordinary cascade.
 * See the longer note in `Checkbox.tsx`.
 *
 * The names are shared with `Checkbox` deliberately, so the two read the same set
 * and neither has to know which it is.
 */
const CONTROL = [
  'group/selection inline-flex items-center gap-2.5',
  'cursor-pointer select-none',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
  // rest
  '[--selection-border:var(--color-input)]',
  '[--selection-mark:0]',
  '[--selection-scale:0.4]',
  '[--selection-ring:transparent]',
  // Hover only brightens the ring; there is nothing to invert, because the centre
  // is empty until the radio is selected.
  'data-[hovered]:[--selection-border:var(--color-foreground)]',
  'data-[selected]:[--selection-border:var(--color-primary)]',
  'data-[selected]:[--selection-mark:1]',
  'data-[selected]:[--selection-scale:1]',
  'data-[focus-visible]:[--selection-ring:var(--color-primary)]',
  // The centre scales in, which is motion, so under reduced motion it stays at
  // full size and cross-fades instead — a fade is not motion and needs no query.
  'motion-reduce:[--selection-scale:1]',
].join(' ')

const DOT = [
  'relative size-[18px] flex-none rounded-full',
  'border border-(--selection-border) bg-transparent',
  'outline-1 outline-offset-[3px] outline-(--selection-ring)',
  'transition-[border-color,outline-color] duration-(--duration-fast) ease-pulse',
].join(' ')

/** The 10px centre, the sheet's `::after` at `inset: 4px`. */
const CENTRE = [
  'absolute inset-[3px] rounded-full bg-primary',
  'opacity-(--selection-mark) scale-(--selection-scale)',
  // **`scale`, not `transform`.** The property this animates is the CSS `scale` at `:62`, and a
  // transition that names `transform` does not cover it — the centre popped in while only the
  // fade ran. The `motion-reduce` rule above keeps it still for anyone who asked for that.
  'transition-[opacity,scale] duration-(--duration-fast) ease-pulse',
].join(' ')

/** The sheet shares `.ds-check-label` between the two controls: 13px, 80%. */
const TEXT = 'text-[13px] text-foreground/80'

/** The sheet's `<fieldset class="stack ds-field">`: legend, controls, hint. */
const GROUP = 'group flex'

export interface RadioProps extends Omit<
  AriaRadioProps,
  'isDisabled' | 'children' | 'className' | 'ref'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLLabelElement>
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaRadioProps['isDisabled']
  /**
